demo.program:
// SPICE purpose demo (simulated model)
var q=['where is the spacecraft?','where is the target?','where does the camera point?'];
for(var i=0;i<q.length;i++){console.log('SPICE answers: '+q[i]);}
console.log('observation geometry, solved');

// SPK interpolation demo (simulated model)
var c=[7000,7.5,0.01];
var t=3600;
var pos=c[0]+c[1]*t+c[2]*t*t;
console.log('SPK: r(t='+t+'s)='+pos.toFixed(1)+'km (polynomial eval)');

// CK attitude demo (simulated model)
var q=[1,0,0,0], w=[0,0,0.001];
console.log('CK: q=['+q+'] w='+w[2]+' rad/s');
console.log('attitude history archived');

// Frame chain demo (simulated model)
var chain=['PCK: Mars pole','FK: spacecraft frame','IK: camera FOV 5deg','CK: attitude','SPK: position'];
for(var i=0;i<chain.length;i++){console.log(chain[i]);}
console.log('geometry chain complete');

// Time kernel demo (simulated model)
var ticks=1e9, rate=256, leap=37;
var et=ticks/rate, utc=et-leap;
console.log('ticks '+ticks+' -> ET '+et+'s -> UTC '+utc+'s');
console.log('SCLK+LSK chain applied');

// DSK intercept demo (simulated model)
var plates=1200, hits=0;
for(var i=0;i<10;i++){if((i*37)%3!==0)hits++;}
console.log('ray vs '+plates+' plates: '+hits+'/10 rays hit');
console.log('DSK surface intercept');

// CSPICE-style call demo (simulated model)
function spkezr(targ){return {pos:[targ*1000,0,0],lt:targ*0.005};}
var s=spkezr(500);
console.log('spkezr: pos='+s.pos+' light-time='+s.lt+'s');
console.log('CSPICE routine pattern');

// Event search demo (simulated model)
var events=[];
for(var t=0;t<100;t+=10){if(Math.sin(t/20)>0.9)events.push(t);}
console.log('occultations at t='+events.join(','));
console.log('GF found '+events.length+' events');

// Illumination demo (simulated model)
var inc=30*Math.PI/180;
var flux=Math.cos(inc);
console.log('incidence 30deg -> flux factor '+flux.toFixed(3));
console.log('ilumin-style angles computed');

// Occultation demo (simulated model)
var sep=[5,2,0.5,3];
for(var i=0;i<sep.length;i++){console.log('t+'+i+'h separation '+sep[i]+'deg '+(sep[i]<1?'OCCULTED':'clear'));}
console.log('blackout windows found');

// Mars relay demo (simulated model)
var passes=['06:12','08:47','21:03'];
for(var i=0;i<passes.length;i++){console.log('relay pass '+passes[i]+' (no Earth occult)');}
console.log(passes.length+' relay windows');

// Kernel version demo (simulated model)
var k=[['v1',0.8],['v2',0.2],['v3',0.05]];
for(var i=0;i<k.length;i++){console.log(k[i][0]+': residual '+k[i][1]+'km');}
console.log('newer kernels, smaller residuals');

// Validation demo (simulated model)
var pred=3600, obs=3601;
console.log('predicted '+pred+'s observed '+obs+'s err='+(obs-pred)+'s');
console.log(Math.abs(obs-pred)<5?'GEOMETRY VALIDATED':'FAILED');

// Query pattern demo (simulated model)
var steps=['furnsh kernels','spkezr state','pxform frames','unload'];
for(var i=0;i<steps.length;i++){console.log((i+1)+'. '+steps[i]);}
console.log('geometry answered in '+steps.length+' steps');

// SPICE chain demo (simulated model)
var c=['kernels','toolkit','finder','plan','fly'];
for(var i=0;i<c.length;i++){console.log((i+1)+'. '+c[i]);}
console.log('SPICE chain complete');
